      "after": "    maintainFocus (event) {
      const focusableNodes = this.getFocusableNodes()
      const focusableNodesWithoutClose = focusableNodes.filter(node => !node.hasAttribute(this.config.closeTrigger))
      const usableNodes = focusableNodesWithoutClose.length ? focusableNodesWithoutClose : focusableNodes

      // if disableFocus is true
      if (!this.modal.contains(document.activeElement)) {
        usableNodes[0].focus()
      } else {
        const focusedItemIndex = usableNodes.indexOf(document.activeElement)

        if (event.shiftKey && focusedItemIndex === 0) {
          usableNodes[usableNodes.length - 1].focus()
          event.preventDefault()
        }

        if (!event.shiftKey && usableNodes.length > 0 && focusedItemIndex === usableNodes.length - 1) {
          usableNodes[0].focus()
          event.preventDefault()
        }
      }
    }"
